# Let me search for any specific numbers in context in more detail
import json
import re

# Search for quarter-specific GDP mentions in both bulletins
# Look for things like "Q1 2015", "Q2 2015", etc with GDP context

data_2020 = json.load(open('/app/resources/treasury_bulletin_2020_03.json'))
data_2016 = json.load(open('/app/resources/treasury_bulletin_2016_03.json'))

all_quarters = {}

for year in range(2013, 2020):
    for q in range(1, 5):
        all_quarters[f"Q{q} {year}"] = []

# Search through all text elements for quarter + GDP mentions
def search_for_quarters(data, source_name):
    elements = data['document']['elements']
    for el in elements:
        if el.get('type') == 'text':
            content = el.get('content', '') or ''
            if 'gdp' in content.lower() or 'growth' in content.lower():
                # Look for quarter patterns
                for year in range(2013, 2020):
                    for q in range(1, 5):
                        # Check if this quarter is mentioned with a percentage
                        pattern = rf'(?:Q{q}|{q}(?:st|nd|rd|th)\s+quarter).{{0,100}}(\d+\.?\d*)'
                        matches = re.findall(pattern, content, re.IGNORECASE)
                        if matches and year in [int(y) for y in range(2013,2020)]:
                            for m in matches:
                                try:
                                    val = float(m)
                                    if 0 < val < 15:  # Reasonable GDP growth range
                                        print(f"{source_name}: Q{q} {year} - {val}%")
                                except:
                                    pass

search_for_quarters(data_2020, "2020 Bulletin")
search_for_quarters(data_2016, "2016 Bulletin")
