# Let me check ALL pages to see where GDP data might be hidden
import json

data = json.load(open('/app/resources/treasury_bulletin_2020_03.json'))
elements = data['document']['elements']

# Group elements by page_id from bbox
page_elements = {}
for el in elements:
    if el.get('bbox'):
        for b in el.get('bbox'):
            page_id = b.get('page_id')
            if page_id not in page_elements:
                page_elements[page_id] = []
            page_elements[page_id].append(el)

# Now look at which pages have GDP content
for page_id in sorted(page_elements.keys()):
    for el in page_elements[page_id]:
        content = el.get('content', '') or ''
        if content and 'gdp' in content.lower() and 'quarter' in content.lower():
            print(f"Page {page_id}: {el.get('type')}")
            print(f"Content preview: {content[:300]}")
            print("---")
            break
